package edu.ise.seatplan;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.http.*;
import org.apache.poi.ss.usermodel.*;
import java.util.*;
import java.time.LocalDate;

 @RestController @RequestMapping("/api") @CrossOrigin(origins="*") class ApiController {
 final RoomRepository rooms; final ExamRepository exams; final AllocationService allocation;final StudentImportService studentImport;
 ApiController(RoomRepository r,ExamRepository e,AllocationService a,StudentImportService i){rooms=r;exams=e;allocation=a;studentImport=i;}
 @GetMapping("/rooms") List<Room> rooms(){return rooms.findAll();}
 @PostMapping("/rooms") Room addRoom(@RequestBody Room r)throws Exception {if(r.layoutJson==null)r.layoutJson=Layout.defaultLayout(4,5,2);if(r.floor==0)r.floor=6;return rooms.save(r);}
 @PutMapping("/rooms/{id}") Room editRoom(@PathVariable Long id,@RequestBody Room r){r.id=id;return rooms.save(r);}
 @DeleteMapping("/rooms/{id}") void deleteRoom(@PathVariable Long id){rooms.deleteById(id);}
 @PostMapping("/rooms/sample") List<Room> samples()throws Exception{if(rooms.count()==0){rooms.save(new Room("603",4,5,2));rooms.save(new Room("605",4,5,2));rooms.save(new Room("606",4,7,2));Room lab=new Room("612 (Lab)",3,5,2);Layout l=new Layout(List.of(new Column(java.util.stream.IntStream.range(0,5).mapToObj(i->new Bench(3,List.of(),2)).toList()),new Column(java.util.stream.IntStream.range(0,5).mapToObj(i->new Bench(2,List.of(),1)).toList()),new Column(java.util.stream.IntStream.range(0,5).mapToObj(i->new Bench(3,List.of(),2)).toList())));lab.description="Computer laboratory";lab.mode="SPECIAL";lab.layoutJson=Json.write(l);rooms.save(lab);Room lab2=new Room("614 (Lab)",2,5,2);lab2.description="Computer laboratory";lab2.mode="SPECIAL";rooms.save(lab2);}return rooms.findAll();}
 @GetMapping("/exams") List<Exam> exams(){return exams.findAll();}
 @GetMapping("/exams/{id}") Exam exam(@PathVariable Long id)throws Exception{Exam x=exams.findById(id).orElseThrow();if("MIXED".equals(x.seatingMode)&&x.assignmentsJson!=null&&!"[]".equals(x.assignmentsJson)){List<Long> ids=Json.read(x.roomIdsJson,new com.fasterxml.jackson.core.type.TypeReference<>(){});List<RoomRange> ranges=Json.read(x.rangeRulesJson==null?"[]":x.rangeRulesJson,new com.fasterxml.jackson.core.type.TypeReference<>(){});List<Assignment> assignments=Json.assignments(x.assignmentsJson);Map<String,String> groups=Json.M.readValue(x.studentGroupsJson==null?"{}":x.studentGroupsJson,new com.fasterxml.jackson.core.type.TypeReference<Map<String,String>>(){});try{allocation.validate(assignments,Json.strings(x.studentsJson),ids,true);allocation.validateMixedPairing(assignments,groups,ids);allocation.validateRanges(assignments,ranges);}catch(IllegalArgumentException invalid){x.arrangementWarning="This stored arrangement does not pass current validation: "+invalid.getMessage()+" Regenerate and save it after resolving any range or capacity conflict.";}}return x;}
 @DeleteMapping("/exams/{id}") void deleteExam(@PathVariable Long id){exams.deleteById(id);}
 @PostMapping("/exams") Exam create(@RequestBody Exam x){x.studentsJson="[]";x.studentGroupsJson="{}";x.assignmentsJson="[]";return exams.save(x);}
 @PostMapping("/exams/{id}/import") Map<String,Object> importUsns(@PathVariable Long id,@RequestParam("file") MultipartFile f,@RequestParam(defaultValue="-1") int sheetIndex,@RequestParam(defaultValue="-1") int column,@RequestParam(defaultValue="-1") int semesterColumn,@RequestParam(defaultValue="true") boolean detect)throws Exception {exams.findById(id).orElseThrow();return studentImport.preview(f,sheetIndex,column,semesterColumn,detect);}
 @PostMapping("/exams/{id}/students") Exam students(@PathVariable Long id,@RequestBody Map<String,Object>b)throws Exception{Exam x=exams.findById(id).orElseThrow();List<String> ss=(List<String>)b.getOrDefault("students",List.of());List<String> normalized=ss.stream().map(v->v.trim().toUpperCase(Locale.ROOT)).toList();if(normalized.stream().anyMatch(v->!v.matches("[A-Z0-9]{8,20}")))throw new IllegalArgumentException("An eligible USN is malformed. Correct or exclude the row before continuing.");if(new HashSet<>(normalized).size()!=normalized.size())throw new IllegalArgumentException("Duplicate USNs remain. Correct or exclude duplicate rows before continuing.");Map<String,String> groups=Json.M.convertValue(b.getOrDefault("groups",Map.of()),new com.fasterxml.jackson.core.type.TypeReference<>(){});if("MIXED".equals(x.seatingMode)){if(x.semester==null||x.semester.isBlank()||x.semesterB==null||x.semesterB.isBlank()||x.semester.equals(x.semesterB))throw new IllegalArgumentException("Enter two different semester labels before importing students.");if(normalized.stream().anyMatch(u->!(x.semester.equals(groups.get(u))||x.semesterB.equals(groups.get(u)))))throw new IllegalArgumentException("Map every eligible USN cohort to one of the two semesters before continuing.");if(normalized.stream().noneMatch(u->x.semester.equals(groups.get(u)))||normalized.stream().noneMatch(u->x.semesterB.equals(groups.get(u))))throw new IllegalArgumentException("Both semesters must have at least one eligible student.");}x.studentsJson=Json.write(normalized);x.studentGroupsJson=Json.write(groups);x.excludedJson=Json.write((List<String>)b.getOrDefault("excluded",List.of()));x.importedJson=Json.write(b.getOrDefault("imported",List.of()));return exams.save(x);}
 @PutMapping("/exams/{id}/rooms") Exam selectRooms(@PathVariable Long id,@RequestBody Map<String,Object>b)throws Exception{Exam x=exams.findById(id).orElseThrow();x.roomIdsJson=Json.write(((List<?>)b.get("roomIds")).stream().map(v->Long.valueOf(v.toString())).toList());return exams.save(x);}
 @GetMapping("/exams/{id}/suggest-ranges") Map<String,Object> suggestRanges(@PathVariable Long id)throws Exception{Exam x=exams.findById(id).orElseThrow();List<String> students=Json.strings(x.studentsJson);List<Long> ids=Json.read(x.roomIdsJson,new com.fasterxml.jackson.core.type.TypeReference<>(){});return allocation.suggestRanges(students,ids,List.of(),"MIXED".equals(x.seatingMode));}
 @PostMapping("/exams/{id}/suggest-ranges") Map<String,Object> reshuffleRanges(@PathVariable Long id,@RequestBody(required=false) Map<String,Object>b)throws Exception{Exam x=exams.findById(id).orElseThrow();List<String> students=Json.strings(x.studentsJson);List<Long> ids=Json.read(x.roomIdsJson,new com.fasterxml.jackson.core.type.TypeReference<>(){});List<RoomRange> previous=b==null?List.of():Json.M.convertValue(b.getOrDefault("previousRanges",List.of()),new com.fasterxml.jackson.core.type.TypeReference<>(){});return allocation.suggestRanges(students,ids,previous,"MIXED".equals(x.seatingMode));}
 @PutMapping("/exams/{id}/ranges") Exam ranges(@PathVariable Long id,@RequestBody Map<String,Object>b)throws Exception{Exam x=exams.findById(id).orElseThrow();x.rangeRulesJson=Json.write(b.getOrDefault("ranges",List.of()));x.grouping="RANGE";return exams.save(x);}
 @PostMapping("/exams/{id}/generate") Map<String,Object> generate(@PathVariable Long id,@RequestParam(defaultValue="false") boolean replace)throws Exception{Exam x=exams.findById(id).orElseThrow();if(x.saved&&!replace)throw new IllegalArgumentException("Saved arrangement replacement requires confirmation.");List<String> students=Json.strings(x.studentsJson);List<Long> ids=Json.read(x.roomIdsJson,new com.fasterxml.jackson.core.type.TypeReference<>(){});List<RoomRange> ranges=Json.read(x.rangeRulesJson==null?"[]":x.rangeRulesJson,new com.fasterxml.jackson.core.type.TypeReference<>(){});Map<String,String> groups=Json.M.readValue(x.studentGroupsJson==null?"{}":x.studentGroupsJson,new com.fasterxml.jackson.core.type.TypeReference<>(){});boolean mixed="MIXED".equals(x.seatingMode);List<Assignment>a=allocation.generateByRanges(students,ids,ranges,groups,x.seatingMode,x.mixPattern,x.semester,x.semesterB);allocation.validate(a,students,ids,mixed);if(mixed)allocation.validateMixedPairing(a,groups,ids);allocation.validateRanges(a,ranges);int capacity=allocation.seats(ids,mixed).size();if(!replace){x.assignmentsJson=Json.write(a);x.originalJson=x.assignmentsJson;x.originalRangeRulesJson=x.rangeRulesJson==null?"[]":x.rangeRulesJson;x.saved=false;x.revision++;exams.save(x);}return Map.of("assignments",a,"capacity",capacity,"assigned",a.size(),"unused",Math.max(0,capacity-a.size()));}
 @PutMapping("/exams/{id}/assignments") Exam assignments(@PathVariable Long id,@RequestBody Map<String,Object>b)throws Exception{Exam x=exams.findById(id).orElseThrow();List<Assignment>a=Json.M.readValue(Json.write(b.get("assignments")),new com.fasterxml.jackson.core.type.TypeReference<>(){});List<Long> ids=Json.read(x.roomIdsJson,new com.fasterxml.jackson.core.type.TypeReference<>(){});List<RoomRange> ranges=Json.read(x.rangeRulesJson==null?"[]":x.rangeRulesJson,new com.fasterxml.jackson.core.type.TypeReference<>(){});boolean mixed="MIXED".equals(x.seatingMode);allocation.validate(a,Json.strings(x.studentsJson),ids,mixed);if(mixed)allocation.validateMixedPairing(a,Json.M.readValue(x.studentGroupsJson==null?"{}":x.studentGroupsJson,new com.fasterxml.jackson.core.type.TypeReference<Map<String,String>>(){}),ids);allocation.validateRanges(a,ranges);x.assignmentsJson=Json.write(a);x.revision++;return exams.save(x);}
 @PostMapping("/exams/{id}/save") Exam save(@PathVariable Long id)throws Exception{Exam x=exams.findById(id).orElseThrow();List<Long> ids=Json.read(x.roomIdsJson,new com.fasterxml.jackson.core.type.TypeReference<>(){});List<RoomRange> ranges=Json.read(x.rangeRulesJson==null?"[]":x.rangeRulesJson,new com.fasterxml.jackson.core.type.TypeReference<>(){});List<Assignment>a=Json.assignments(x.assignmentsJson);boolean mixed="MIXED".equals(x.seatingMode);allocation.validate(a,Json.strings(x.studentsJson),ids,mixed);if(mixed)allocation.validateMixedPairing(a,Json.M.readValue(x.studentGroupsJson==null?"{}":x.studentGroupsJson,new com.fasterxml.jackson.core.type.TypeReference<Map<String,String>>(){}),ids);allocation.validateRanges(a,ranges);x.saved=true;x.originalJson=x.assignmentsJson;x.originalRangeRulesJson=x.rangeRulesJson==null?"[]":x.rangeRulesJson;return exams.save(x);}
 @PostMapping("/exams/{id}/discard") Exam discard(@PathVariable Long id)throws Exception{Exam x=exams.findById(id).orElseThrow();x.assignmentsJson=x.originalJson;x.rangeRulesJson=x.originalRangeRulesJson==null?"[]":x.originalRangeRulesJson;List<Long> ids=Json.read(x.roomIdsJson,new com.fasterxml.jackson.core.type.TypeReference<>(){});List<RoomRange> ranges=Json.read(x.rangeRulesJson,new com.fasterxml.jackson.core.type.TypeReference<>(){});List<Assignment> restored=Json.assignments(x.assignmentsJson);boolean mixed="MIXED".equals(x.seatingMode);allocation.validate(restored,Json.strings(x.studentsJson),ids,mixed);if(mixed)allocation.validateMixedPairing(restored,Json.M.readValue(x.studentGroupsJson==null?"{}":x.studentGroupsJson,new com.fasterxml.jackson.core.type.TypeReference<Map<String,String>>(){}),ids);allocation.validateRanges(restored,ranges);return exams.save(x);}
 @ExceptionHandler(Exception.class) ResponseEntity<Map<String,String>> error(Exception e){return ResponseEntity.badRequest().body(Map.of("error",Optional.ofNullable(e.getMessage()).orElse("Request could not be processed.")));}
}
